            aScatter = TwistMix64::DiffuseB((aScatter ^ aTwistDomainWordScatter));
            //
            aOrbiterF = (aWandererA + RotL64(aPrevious, 41U)) + 0x0BDE3087EEC7111DULL;
            aOrbiterG = (aWandererB + RotL64(aCross, 35U)) + 0x0D9AC168FEB5747AULL;
            aOrbiterE = ((aWandererK + RotL64(aScatter, 14U)) + RotL64(aCarry, 19U)) + 0x618FCDAA96A7A6D1ULL;
            aOrbiterK = (aWandererE + RotL64(aIngress, 43U)) + 0xD1BEF7C6E24B3AC5ULL;
