            aOrbiterB = (((aWandererB + RotL64(aPrevious, 19U)) + RotL64(aCarry, 51U)) + 0x8D2544BCD01BA7CCULL) + aOASaltG[((aIndex + 455U)) & S_SALT1];
            //
            aOrbiterK = ((aOrbiterK + aOrbiterE) + 0xC2D39278E4A4C602ULL) + aOUSaltG[(((511U - aIndex) + 208U)) & S_SALT1];
