            aOrbiterK = ((aOrbiterK + aOrbiterH) + 0xCDAAE0A308E84B12ULL) + aOUSaltE[(((511U - aIndex) + 130U)) & S_SALT1];
            aOrbiterC = ((aOrbiterC ^ aOrbiterK) ^ 0x8810DA59913083EBULL) ^ aOUSaltH[((aIndex + 5U)) & S_SALT1];
