            aOrbiterI = ((aWandererB + RotL64(aPrevious, 41U)) + 0xCF3D075B8D44DA08ULL) + aOASaltD[(((511U - aIndex) + 411U)) & S_SALT1];
            aOrbiterE = (((aWandererE + RotL64(aCross, 53U)) + RotL64(aCarry, 37U)) + 0x2CDAF61818B3133BULL) + aOASaltH[((aIndex + 57U)) & S_SALT1];
