            aOrbiterI = (((aWandererC + RotL64(aPrevious, 27U)) + RotL64(aCarry, 5U)) + 0xBE5F14C38AB9E81DULL) + aOASaltB[((aIndex + 29U)) & S_SALT1];
            aOrbiterB = ((aWandererI + RotL64(aScatter, 51U)) + 0xAAFA4702678314D0ULL) + aOASaltC[((aIndex + 463U)) & S_SALT1];
