            aOrbiterK = (aOrbiterK + aOrbiterE) + 0x12A86D42F4414D15ULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterK) ^ 0x43419EBF89E46F79ULL;
            aOrbiterI = RotL64((aOrbiterI * 0x2C6733E9A0977D55ULL), 21U);
            //
            aOrbiterC = ((aOrbiterC + aOrbiterI) + 0x0381F94614DB5A59ULL) + aOUSaltE[(((511U - aIndex) + 51U)) & S_SALT1];
            aOrbiterB = ((aOrbiterB ^ aOrbiterC) ^ 0xD3420BB2F5B8965DULL) ^ aOUSaltB[(((511U - aIndex) + 406U)) & S_SALT1];
            aOrbiterB = RotL64((aOrbiterB * 0x2CE1AFB7311DA46BULL), 5U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterF) + 0x93251EE24E0F764DULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterB) ^ 0xB13176D92F97AEF6ULL;
