            aOrbiterF = (((aWandererD + RotL64(aPrevious, 29U)) + RotL64(aCarry, 21U)) + 0xC0C4C827BE4FDD24ULL) + aOASaltA[((aIndex + 275U)) & S_SALT1];
            aOrbiterK = ((aWandererB + RotL64(aScatter, 35U)) + RotL64(aCarry, 51U)) + 0x5BB3D89646EF0F74ULL;
            aOrbiterH = ((aWandererK + RotL64(aIngress, 18U)) + 0x9AE884B89D7C124BULL) + aOASaltD[((aIndex + 501U)) & S_SALT1];
