            //
            aOrbiterI = (aOrbiterI + aOrbiterJ) + 0x0E732CEDCE608913ULL;
            aOrbiterD = ((aOrbiterD ^ aOrbiterI) ^ 0x6FEA398F8886DBBCULL) ^ aOUSaltH[(((511U - aIndex) + 301U)) & S_SALT1];
            aOrbiterD = RotL64((aOrbiterD * 0x93826A4248215F37ULL), 41U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterC) + 0x409B896EE8606B11ULL;
