            aScatter = (RotL64(aIngress, 18U) ^ RotL64(aCross, 37U)) + (RotL64(aPrevious, 3U) ^ RotL64(aCarry, 53U));
            aScatter = TwistMix64::DiffuseC((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterF = ((aWandererG + RotL64(aScatter, 43U)) + 0xC588B2E0A2B33DA8ULL) + aOASaltF[((aIndex + 175U)) & S_SALT1];
            aOrbiterK = ((aWandererH + RotL64(aPrevious, 35U)) + 0xB626EF0DEB5B4188ULL) + aOASaltH[(((511U - aIndex) + 319U)) & S_SALT1];
            aOrbiterJ = ((aWandererJ + RotL64(aCross, 29U)) + 0xBE8DCE1FD5EC93B6ULL) + aOASaltG[(((511U - aIndex) + 288U)) & S_SALT1];
            aOrbiterB = ((aWandererC + RotL64(aIngress, 23U)) + 0x5011E92BD77F768AULL) + aOASaltA[((aIndex + 127U)) & S_SALT1];
