            aOrbiterC = ((aWandererI + RotL64(aIngress, 11U)) + RotL64(aCarry, 43U)) + 0xC58C8B81578F8A7EULL;
            //
            aOrbiterF = (aOrbiterF + aOrbiterK) + 0xEC15E8EEA754ED58ULL;
