            aOrbiterG = RotL64((aOrbiterG * 0xA57D896AE4D203E7ULL), 57U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterC) + 0xE7E173A4CD544ED0ULL;
            aOrbiterF = ((aOrbiterF ^ aOrbiterE) ^ 0x3AA198DD052F89FBULL) ^ aOUSaltB[(((511U - aIndex) + 321U)) & S_SALT1];
