            //
            aIngress = (RotL64(aVaporLaneA[((aIndex + 7606U)) & S_BLOCK1], 27U) ^ RotL64(aVaporLaneB[((aIndex + 903U)) & S_BLOCK1], 39U));
            aIngress ^= (RotL64(aMagmaLaneC[((aIndex + 4831U)) & S_BLOCK1], 19U) ^ RotL64(aWindLaneA[((S_BLOCK1 - aIndex + 7354U)) & S_BLOCK1], 50U));
