            aCross ^= (RotL64(aLightningLaneD[((S_BLOCK1 - aIndex + 13430U)) & S_BLOCK1], 13U) ^ RotL64(aPlasmaLaneD[((aIndex + 14082U)) & S_BLOCK1], 22U));
            aCross = TwistMix64::DiffuseB((aCross ^ aKeyRotateBDomainWordCross));
