            aWandererK = aWandererK ^ ((RotL64(aPrevious, 35U) + aOrbiterH) + RotL64(aOrbiterJ, 27U));
            aWandererF = aWandererF + (((RotL64(aIngress, 27U) + RotL64(aOrbiterB, 3U)) + aOrbiterF) + RotL64(aCarry, 57U));
            aWandererE = aWandererE ^ ((RotL64(aScatter, 18U) + RotL64(aOrbiterK, 60U)) + aOrbiterF);
