            aOrbiterG = RotL64((aOrbiterG * 0x28BA54AA9D71422BULL), 39U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterK) + 0x8EB922724AE5CD98ULL;
            aOrbiterA = ((aOrbiterA ^ aOrbiterF) ^ 0x93A6519C65902571ULL) ^ aOUSaltA[((aIndex + 334U)) & S_SALT1];
            aOrbiterA = RotL64((aOrbiterA * 0xAA70CF627304FB29ULL), 5U);
            //
            aOrbiterA = ((aOrbiterA + aOrbiterB) + 0x17C7EC93EF17E4A5ULL) + aOUSaltH[(((511U - aIndex) + 9U)) & S_SALT1];
            aOrbiterJ = (aOrbiterJ ^ aOrbiterA) ^ 0xAE548DB2BDA719AAULL;
